-- ── 2. Create college_fees table ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS college_fees (
  id           UUID   PRIMARY KEY DEFAULT gen_random_uuid(),
  college_code TEXT   NOT NULL REFERENCES colleges(code) ON DELETE CASCADE,
  category     TEXT   NOT NULL,
  amount       BIGINT NOT NULL,
  UNIQUE (college_code, category)
);

ALTER TABLE college_fees ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "anon_read_fees" ON college_fees;
CREATE POLICY "anon_read_fees" ON college_fees FOR SELECT TO anon USING (true);

